const i=[{id:"suggestion-S01",title:"Peerdeman et coll. · 2016 · Agir sur les attentes et la douleur des patients",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 études regroupant 1 256 patients sélectionnés ont trouvé une douleur déclarée plus faible après des interventions sur les attentes : g = 0,61, IC à 95 % de 0,42 à 0,79 ; après correction du biais, 0,43, de 0,24 à 0,62.",limitation:"Ces interventions cliniques diffèrent d’une phrase écrite pour soi. Forte hétérogénéité ; moins de douleur déclarée ne signifie pas guérison de sa cause. Après retrait d’une valeur extrême, l’estimation pour l’anxiété était 0,03, IC de −0,21 à 0,26."},{id:"suggestion-S02",title:"Epton et coll. · 2015 · Auto-affirmation et comportements de santé",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Réfléchir à ses valeurs, avec des informations de santé, montrait de petites différences moyennes dans l’accueil des messages, les intentions et le comportement, sur 144 tests de résultats. Comportement : d = 0,32, IC à 95 % de 0,19 à 0,44.",limitation:"144 tests ne correspondent pas forcément à des études distinctes. Les effectifs par résultat se recoupent. Ces travaux ne prouvent pas l’effet d’une réflexion seule sur les valeurs, de formules positives répétées ou du court exercice ODA pour adultes."},{id:"suggestion-S03",title:"Kross et coll. · 2014 · Expériences sur le discours intérieur avec du recul",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Sept expériences courtes réunissaient 585 personnes. Dans l’étude 2, réfléchir trois minutes avec son prénom ou sans la première personne avant une interaction sociale améliorait la performance évaluée par des observateurs.",limitation:"Contextes surtout étudiants et d’évaluation sociale. L’anxiété avant l’interaction ne diminuait pas significativement dans l’étude 2 ; le rétablissement après était plus net. L’adaptation courte d’ODA, conseil puis action, n’est ni un traitement ni un effet garanti."},{id:"suggestion-S04",title:"Hatzigeorgiadis et coll. · 2011 · Discours intérieur et performance sportive",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 études, 62 effets et 2 741 participants : bénéfice moyen sur la performance sportive, d+ = 0,48, IC à 95 % de 0,38 à 0,58. Les estimations variaient selon les tâches et l’entraînement.",limitation:"Certaines études n’avaient pas de groupe témoin. Comparer leurs caractéristiques n’établit ni dose optimale ni supériorité universelle des consignes. Le transfert au bureau et l’ensemble du modèle de Gallwey n’ont pas été testés."},{id:"suggestion-S05",title:"Zhang et coll. · 2025 · Auto-affirmation et bien-être",url:"https://hub.hku.hk/handle/10722/366517",type:"research",finding:"Le résumé universitaire rapporte 67 articles et 129 tests indépendants chez des populations non cliniques, avec de petits bénéfices moyens pour la perception de soi et le bien-être.",limitation:"Méthodes complètes, effectif total, intervalles de confiance, mesure exacte de l’effet et durées de suivi inaccessibles. Cela ne valide pas chaque formule d’affirmation ni un rituel particulier."},{id:"suggestion-S06",title:"Wang, Wang et Gai · 2021 · Résultat souhaité, obstacle et réponse prévue",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 articles, 24 effets indépendants, 15 907 participants : bénéfice moyen du contraste mental avec plans « si… alors… » pour atteindre les objectifs, g = 0,336, IC de 0,229 à 0,443 ; corrigé du biais, 0,242, de 0,143 à 0,342.",limitation:"Méthodes et comparaisons variées. Cela ne valide ni la fiche ODA complète, ni les mots positifs comme ingrédient actif, ni une rêverie au coucher suivie d’un plan le lendemain matin."},{id:"suggestion-S07",title:"Wood, Perunovic et Lee · 2009 · Affirmations positives sur soi",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Le résumé rapporte des réactions immédiates moins favorables chez certains participants à faible estime de soi répétant une affirmation très positive, avec des bénéfices limités à plus haute estime de soi.",limitation:"Effectifs originaux, nombre de répétitions et effets chiffrés non vérifiés. Deux études ultérieures n’ont pas reproduit ce résultat. Aucun seuil clinique ni mécanisme universel de décalage n’est établi."},{id:"suggestion-S08",title:"Flynn et Bordieri · 2020 · Études de réplication sur les affirmations",url:"https://contextualscience.org/publications/flynn_bordieri_2020",type:"research",finding:"Deux expériences universitaires en situation analogue, environ 225 et 237 participants, n’ont pas reproduit les effets prévus sur l’humeur, l’estime de soi du moment ou leur variation selon l’estime de soi habituelle.",limitation:"Seul le résumé des auteurs était disponible. Effets chiffrés, intervalles de confiance et précision inaccessibles. Un résultat nul n’établit ni bénéfice universel ni innocuité universelle."},{id:"suggestion-S09",title:"Lally et coll. · 2010 · Habitudes du quotidien",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 volontaires répétaient des gestes alimentaires, de boisson ou d’activité dans des contextes récurrents pendant 84 jours. Le délai d’automaticité estimé variait beaucoup parmi les 39 modèles satisfaisants.",limitation:"Étude observationnelle, pas essai d’affirmations. La médiane estimée de 66 jours n’est pas une échéance ; certaines estimations dépassent l’observation. Aucune preuve d’automaticité dès vendredi ni de changement durable en 21 jours."},{id:"suggestion-S10",title:"Paller, Creery et Schechtman · 2021 · Mémoire et sommeil",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"Cette synthèse aborde la réactivation de connaissances pendant le sommeil et les possibilités limitées d’apprendre des associations simples en dormant.",limitation:"Synthèse narrative, sans effet regroupé. Le traitement des souvenirs ne prouve ni une réceptivité somnolente aux injonctions personnelles, ni le rituel de Murphy, ni des compétences complexes installées par des enregistrements, ni des résultats causés par la pensée."},{id:"suggestion-S11",title:"Cohen et coll. · 2006 · Écriture sur les valeurs dans un collège",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/cohen_et_al._2006_-_reducing_the_racial_achievement_gap.pdf",type:"research",finding:"Deux expériences de terrain randomisées réunissaient 243 élèves de septième année dans un établissement américain. Environ quinze minutes d’écriture sur les valeurs amélioraient les notes du cours ciblé chez les élèves noirs, dans ce contexte.",limitation:"Aucun effet significatif chez les élèves blancs. Une grande réplication ultérieure a donné un résultat nul. Cela n’établit ni bénéfice scolaire universel, ni confiance adulte, ni effet immédiat sur l’humeur."},{id:"suggestion-S12",title:"Hanselman et coll. · 2017 · Grande réplication de l’auto-affirmation par les valeurs",url:"https://files.eric.ed.gov/fulltext/ED578033.pdf",type:"research",finding:"Une réplication auprès d’une nouvelle cohorte de collégiens n’a trouvé aucun bénéfice significatif sur la moyenne scolaire ciblée. Sa précision permettait d’écarter des bénéfices d’au moins 0,10 écart-type.",limitation:"Contexte scolaire et résultat mesuré comptent. Cela ne rend pas toute réflexion sur les valeurs inutile et ne réfute pas les résultats sur les messages de santé. Le texte lié est un manuscrit accepté."},{id:"suggestion-S13",title:"Toth et coll. · 2020 · Répétition mentale et performance",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"Le résumé universitaire rapporte 37 études sur des tâches et compétences, avec une petite association à la performance après correction du biais de publication, r = 0,131.",limitation:"Méthodes complètes, effectif total et intervalle de confiance inaccessibles. Répéter une tâche ne valide ni l’autosuggestion au coucher, ni un rituel de marque, ni une durée universelle de répétition."},{id:"suggestion-S15",title:"Émile Coué · Édition anglaise de 1922 · Autosuggestion consciente",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"Ce texte historique prescrit vingt répétitions à voix basse au réveil et au coucher, comptées sur des nœuds, les yeux fermés et sans forcer.",limitation:"Anecdotes et témoignages ne sont pas des preuves contrôlées. Vingt répétitions est une prescription historique, pas une dose démontrée. Les lois universelles sur l’imagination et les promesses de guérison du livre ne sont pas étayées."},{id:"suggestion-S16",title:"Joseph Murphy · The Power of Your Subconscious Mind · Présentation de l’éditeur",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"La présentation situe le livre et met en avant ses enseignements sur la croyance et l’imagination.",limitation:"Aucune preuve d’essai fournie. Phrase du coucher, scène de félicitations et passage sur la gratitude non vérifiés. Les travaux sur mémoire et sommeil ne valident ni avantage de la somnolence, ni attraction subconsciente, ni guérison."},{id:"suggestion-S17",title:"Oettingen et coll. · 2015 · Contraste mental et gestion du temps",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"L’étude 1 réunissait dans une séance le résultat souhaité, l’obstacle et la réponse, puis un plan « si… alors… » avec les lieu et moment habituels, avant d’organiser la semaine.",limitation:"Étudiants allemands ; le résultat examiné était les heures planifiées, pas le travail réalisé. Aucune durée fixe en minutes ni horaire spécial au coucher n’était établi."},{id:"suggestion-S18",title:"Louise Hay · Qu’est-ce que le travail avec le miroir ?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"Le site de l’autrice décrit des affirmations positives prononcées face à un miroir et un programme de 21 jours.",limitation:"Présentation d’une pratique, pas preuve d’efficacité. Aucun essai contrôlé de cet ensemble n’a été trouvé dans la recherche du dossier ; c’est une limite de recherche. Ni supériorité du miroir ni délai d’habitude de 21 jours établis."},{id:"suggestion-S19",title:"Joe Dispenza · Breaking the Habit of Being Yourself · Édition de l’éditeur",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/9781401938093/",type:"technique",finding:"L’éditeur date le livre de poche de février 2013 ; le livre numérique a paru en 2012.",limitation:"Présentation promotionnelle, pas preuve contrôlée. Routine exacte de dix minutes, séquence de gratitude et signal de changement non vérifiés. Attraction quantique, commandes génétiques et guérison non établies."},{id:"suggestion-S20",title:"NIMH · Trouver de l’aide en santé mentale",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Ces recommandations officielles indiquent comment obtenir un soutien qualifié en santé mentale ou une aide de crise. Détresse persistante, difficultés majeures au quotidien et pensées de se faire du mal nécessitent une aide adaptée.",limitation:"ODA ne diagnostique ni ne traite. Hors des États-Unis, utilise les services locaux. Des symptômes physiques inquiétants demandent un avis médical ; le discours intérieur ne doit pas présenter la maltraitance ou un danger réel comme sans risque."},{id:"murphy-subconscious",title:"Joseph Murphy · The Power of Your Subconscious Mind · Présentation de l’éditeur",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"La présentation situe le livre et met en avant ses enseignements sur la croyance et l’imagination.",limitation:"Aucune preuve d’essai fournie. Phrase du coucher, scène de félicitations et passage sur la gratitude non vérifiés. Les travaux sur mémoire et sommeil ne valident ni avantage de la somnolence, ni attraction subconsciente, ni guérison."},{id:"expectation-suggestion",title:"Peerdeman et coll. · 2016 · Agir sur les attentes et la douleur des patients",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 études regroupant 1 256 patients sélectionnés ont trouvé une douleur déclarée plus faible après des interventions sur les attentes : g = 0,61, IC à 95 % de 0,42 à 0,79 ; après correction du biais, 0,43, de 0,24 à 0,62.",limitation:"Ces interventions cliniques diffèrent d’une phrase écrite pour soi. Forte hétérogénéité ; moins de douleur déclarée ne signifie pas guérison de sa cause. Après retrait d’une valeur extrême, l’estimation pour l’anxiété était 0,03, IC de −0,21 à 0,26."},{id:"positive-self-statements",title:"Wood, Perunovic et Lee · 2009 · Affirmations positives sur soi",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Le résumé rapporte des réactions immédiates moins favorables chez certains participants à faible estime de soi répétant une affirmation très positive, avec des bénéfices limités à plus haute estime de soi.",limitation:"Effectifs originaux, nombre de répétitions et effets chiffrés non vérifiés. Deux études ultérieures n’ont pas reproduit ce résultat. Aucun seuil clinique ni mécanisme universel de décalage n’est établi."},{id:"self-affirmation-health",title:"Epton et coll. · 2015 · Auto-affirmation et comportements de santé",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Réfléchir à ses valeurs, avec des informations de santé, montrait de petites différences moyennes dans l’accueil des messages, les intentions et le comportement, sur 144 tests de résultats. Comportement : d = 0,32, IC à 95 % de 0,19 à 0,44.",limitation:"144 tests ne correspondent pas forcément à des études distinctes. Les effectifs par résultat se recoupent. Ces travaux ne prouvent pas l’effet d’une réflexion seule sur les valeurs, de formules positives répétées ou du court exercice ODA pour adultes."},{id:"distanced-self-talk",title:"Kross et coll. · 2014 · Expériences sur le discours intérieur avec du recul",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Sept expériences courtes réunissaient 585 personnes. Dans l’étude 2, réfléchir trois minutes avec son prénom ou sans la première personne avant une interaction sociale améliorait la performance évaluée par des observateurs.",limitation:"Contextes surtout étudiants et d’évaluation sociale. L’anxiété avant l’interaction ne diminuait pas significativement dans l’étude 2 ; le rétablissement après était plus net. L’adaptation courte d’ODA, conseil puis action, n’est ni un traitement ni un effet garanti."},{id:"sport-self-talk",title:"Hatzigeorgiadis et coll. · 2011 · Discours intérieur et performance sportive",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 études, 62 effets et 2 741 participants : bénéfice moyen sur la performance sportive, d+ = 0,48, IC à 95 % de 0,38 à 0,58. Les estimations variaient selon les tâches et l’entraînement.",limitation:"Certaines études n’avaient pas de groupe témoin. Comparer leurs caractéristiques n’établit ni dose optimale ni supériorité universelle des consignes. Le transfert au bureau et l’ensemble du modèle de Gallwey n’ont pas été testés."},{id:"sleep-memory-reactivation",title:"Paller, Creery et Schechtman · 2021 · Mémoire et sommeil",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"Cette synthèse aborde la réactivation de connaissances pendant le sommeil et les possibilités limitées d’apprendre des associations simples en dormant.",limitation:"Synthèse narrative, sans effet regroupé. Le traitement des souvenirs ne prouve ni une réceptivité somnolente aux injonctions personnelles, ni le rituel de Murphy, ni des compétences complexes installées par des enregistrements, ni des résultats causés par la pensée."},{id:"coue-autosuggestion",title:"Émile Coué · Édition anglaise de 1922 · Autosuggestion consciente",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"Ce texte historique prescrit vingt répétitions à voix basse au réveil et au coucher, comptées sur des nœuds, les yeux fermés et sans forcer.",limitation:"Anecdotes et témoignages ne sont pas des preuves contrôlées. Vingt répétitions est une prescription historique, pas une dose démontrée. Les lois universelles sur l’imagination et les promesses de guérison du livre ne sont pas étayées."},{id:"hay-mirror-work",title:"Louise Hay · Qu’est-ce que le travail avec le miroir ?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"Le site de l’autrice décrit des affirmations positives prononcées face à un miroir et un programme de 21 jours.",limitation:"Présentation d’une pratique, pas preuve d’efficacité. Aucun essai contrôlé de cet ensemble n’a été trouvé dans la recherche du dossier ; c’est une limite de recherche. Ni supériorité du miroir ni délai d’habitude de 21 jours établis."}],t=[{schemaVersion:2,revision:2,id:"suggestion-1",courseId:"suggestion",locale:"fr",title:"Tu te critiques ? Choisis une phrase utile",goal:"Choisis une consigne crédible et utilise-la pour un vrai geste dans ta tâche.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tu te traites de nul et la page reste vide ? Remplace ce jugement par une consigne précise.",reason:{id:"suggestion-1-reason",label:"Qu’a coûté cette critique ? Quel geste compte maintenant ?",kind:"text",maxLength:160,optional:!0,suggestions:["Candidature vide ; écrire un premier fait","Correction reportée ; vérifier la date","Aucun coût observé pour le moment"]},why:{id:"suggestion-1-why",label:"Quelle place ce geste ferait-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Une consigne utile dit quoi faire : « Note un fait concret. » Un verdict flatteur te définit. Les affirmations très positives ont des résultats mitigés : une première étude rapportait des réactions immédiates moins favorables chez certains participants ; deux suivantes n’ont pas reproduit ce résultat. Choisir des mots neutres ne pose aucun diagnostic sur toi.","Choisis une tâche qui sert ta direction. Remplace le verdict par une consigne, puis agis utilement. Les recherches sportives ne prouvent pas un bénéfice au bureau. Note le geste et l’effet des mots : aide, pression ou aucun changement."],example:{title:"Camille écrit un premier fait",text:"À 14 h, Camille ouvre sa candidature. « Je suis nulle » lui vient facilement ; « Je suis brillante » sonne faux. Elle essaie « Note un fait concret » et produit une phrase utile sur son expérience. Elle doute toujours. Elle note la phrase et ses doutes, puis prévoit un autre essai au lieu de répéter des compliments pour y croire."}},move:{invitation:"Précise ta tâche et ta consigne ; exemples : candidature de Camille.",instructions:["Précise le document, la question ou l’élément avant d’enregistrer.","Lis la consigne une fois, puis fais la partie utile correspondante."],prompts:[],suggestions:{action:["Écrire une phrase avec « Note un fait concret »","Répondre à la question sur l’expérience professionnelle"],minimum:["Enregistrer une phrase factuelle sur mon expérience","Enregistrer la réponse sur mon expérience"],cue:["À la fin du déjeuner","Après avoir débarrassé le dîner"],place:["À la table de ma cuisine","Dans le document de candidature"],minutes:[2,1,3],fallback:["Laisser le verdict ; écrire un fait de candidature","Demander quel détail professionnel est nécessaire"],observation:["La phrase de candidature que j’ai enregistrée","Les mots m’ont-ils aidé ou mis la pression ?"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Écrire une phrase avec « Note un fait concret »",minimum:"Enregistrer une phrase factuelle sur mon expérience",minutes:2,cueHint:"À la fin du déjeuner",placeHint:"À la table de ma cuisine",obstacleHint:"La phrase devient un nouveau jugement",fallbackHint:"Laisser le verdict ; écrire un fait de candidature",observationHint:"La phrase de candidature que j’ai enregistrée"},stopRule:"Arrête les formulations qui aggravent la détresse. Cherche du soutien si elle persiste ; consulte pour des symptômes inquiétants.",accessibleAlternative:"Écris, dicte ou fais-toi aider ; une consigne neutre suffit."},result:{question:"As-tu produit la partie utile que tu avais choisie ?",observationPrompt:"Qu’as-tu fait pendant cet essai ? Qu’est-ce qui t’a freiné ?"},judgment:{primary:{id:"suggestion-1-decision",scenario:"Camille a deux minutes et les faits nécessaires pour écrire une phrase de candidature. Les compliments sonnent faux et le document reste vide.",question:"Qu’est-ce qui convient à cet essai ?",options:[{id:"suggestion-1-praise",text:"Choisir une affirmation positive plus chaleureuse avant de décider si elle peut commencer à écrire.",feedback:"Des mots chaleureux peuvent plaire, mais Camille sait qu’ils sonnent faux aujourd’hui. Elle peut essayer une consigne neutre et produire une partie utile sans devoir croire aux compliments."},{id:"suggestion-1-fact",text:"Dire « Note un fait concret », puis écrire une phrase de candidature utilisable.",feedback:"Cette consigne décrit une action sous son contrôle et la teste tout de suite. Les mots peuvent aider, ne rien changer ou mettre la pression ; elle peut noter sa production et son ressenti."},{id:"suggestion-1-picture",text:"Imaginer un examen réussi de sa candidature, puis vérifier si elle se sent prête à écrire.",feedback:"Une image peut agréablement préparer, mais elle ne produit pas la partie utile choisie. Les faits sont prêts : une consigne puis un petit geste permettent un essai concret."}],bestOptionId:"suggestion-1-fact"}},carry:{takeaway:"Choisis une consigne utile. Évalue-la avec ce que tu fais réellement.",followUp:{questionId:"suggestion-1-return",question:"Que s’est-il passé avec ton geste ? La consigne a-t-elle aidé ou ajouté de la pression ?",observationPrompt:"Que montrent tes notes sur les faits ?",adjustmentPrompt:"Que garderas-tu ou changeras-tu au prochain signal ?"}},goDeeper:{sections:[{heading:"La crédibilité se choisit ; aucun score ne la décide",paragraphs:["Le résumé accessible de Wood et ses collègues rapportait des réactions immédiates moins favorables à une affirmation très positive chez certains participants à faible estime de soi. Il ne donne pas assez de détails pour prescrire un nombre de répétitions ou prédire une réponse individuelle. Deux expériences universitaires ultérieures de Flynn et Bordieri n’ont pas reproduit le résultat prévu. Les travaux appellent donc à l’incertitude, sans établir que les affirmations positives nuisent à un type précis de personne. (suggestion-S07 ; suggestion-S08)","Ta préférence reste une information utile. Si « Je suis brillante » sonne faux, tu peux choisir « Note un fait concret », modifier les mots, éviter les répétitions ou arrêter. Une note privée de crédibilité peut guider la formulation, mais aucun score ici n’est un seuil clinique validé. ODA n’en déduit pas ton estime de soi et n’impose aucun encouragement. Pars de la tâche réelle pour donner aux mots un travail précis."]},{heading:"Des mots différents, des preuves différentes",paragraphs:["Hatzigeorgiadis et ses collègues ont réuni trente-deux études sur le discours intérieur, avec soixante-deux effets dans le sport et les tâches motrices. Le tableau 1 rapportait 2 741 participants. Le bénéfice moyen de performance n’établit pas le même bénéfice pour les candidatures, les relations ou l’anxiété. Certaines études n’avaient pas de groupe témoin. Les comparaisons entre sous-groupes ne démontrent aucun classement universel entre consignes et encouragements. (suggestion-S04)","La consigne neutre et la petite production écrite proposées aujourd’hui sont une adaptation ODA hors du contexte sportif. Le cours complet n’a pas été testé comme un ensemble. Note séparément tes mots, ton geste et la pression éventuelle. Une phrase peut être crédible sans aider à agir ; elle peut t’aider à démarrer sans réduire tes doutes. Ces distinctions permettent de la garder, la modifier ou l’abandonner sans considérer chaque répétition comme un progrès vers la vie choisie."]}],sourceIds:["suggestion-S07","suggestion-S08","suggestion-S04"]}},{schemaVersion:2,revision:2,id:"suggestion-2",courseId:"suggestion",locale:"fr",title:"Le rituel s’arrête quand l’action commence",goal:"Relie le même geste utile à un signal qui arrive vraiment.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tu répètes le rappel, mais la page reste vide ? Fais suivre le signal d’une action.",reason:{id:"suggestion-2-reason",label:"Si tu répétais des rappels, qu’y gagnais-tu pendant que la tâche attendait ?",kind:"text",maxLength:160,optional:!0,suggestions:["Réconfort bref ; document resté vide","Évité de choisir une première phrase","Aucun essai limité à des rappels"],help:"Pas encore essayé ? Que repousserait une nouvelle lecture du rappel ?"},why:{id:"suggestion-2-why",label:"Quelle place ce geste ferait-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Répéter une phrase et répéter une action sont deux essais différents. Une étude suivait alimentation, boisson et activité à des moments récurrents. L’automaticité s’installait à des rythmes différents ; les affirmations n’étaient pas testées. Les vingt répétitions de Coué sont une prescription historique, pas une dose démontrée.","Relis tes notes : mots crédibles, mais aucun départ ? Garde la tâche et choisis un événement réel. « Après le déjeuner, écrire une phrase de candidature » relie moment et geste. Lis ta consigne une fois si utile, puis écris. Préparer le matériel n’est pas écrire."],example:{title:"Camille choisit le déjeuner",text:"La première consigne de Camille était crédible, mais elle l’a oubliée pendant une matinée chargée. Elle garde sa candidature et choisit la fin du déjeuner. À la table de la cuisine, elle lit une fois « Note un fait concret » et écrit une phrase utilisable. La séance reste courte. Elle note le signal et la production, sans parler d’habitude automatique."}},move:{invitation:"Garde ton geste ; exemples : déjeuner de Camille.",instructions:["Garde geste et minimum ; change le signal si les faits le justifient.","Premier plan ? Précise la production et le créneau avant d’enregistrer."],prompts:[],suggestions:{action:["Après déjeuner, écrire une phrase sur mon expérience","Après le thé, répondre sur mon expérience professionnelle"],minimum:["Enregistrer une phrase factuelle de candidature","Enregistrer la réponse sur mon expérience"],cue:["À la fin du déjeuner","Quand je repose ma tasse de thé"],place:["À la table de ma cuisine","Dans le document de candidature"],minutes:[2,1,3],fallback:["Après dîner, écrire une phrase sur mon expérience","Dicter la phrase de candidature au déjeuner"],observation:["Le moment et la phrase ont-ils eu lieu ?","Lecture du rappel distincte du travail utile"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Après déjeuner, écrire une phrase sur mon expérience",minimum:"Enregistrer une phrase factuelle de candidature",minutes:2,cueHint:"À la fin du déjeuner",placeHint:"À la table de ma cuisine",obstacleHint:"Le créneau du déjeuner passe à la trappe",fallbackHint:"Après dîner, écrire une phrase sur mon expérience",observationHint:"Le moment et la phrase ont-ils eu lieu ?"},stopRule:"Évite les répétitions qui ajoutent détresse ou éveil. Préserve soins, repos et besoins réels de sécurité.",accessibleAlternative:"Rappel écrit, oral ou accessible ; ni perles ni comptage obligatoires."},result:{question:"Le signal est-il arrivé ? As-tu fait la partie prévue ?",observationPrompt:"Qu’as-tu fait pendant cet essai ? Qu’est-ce qui t’a freiné ?"},judgment:{primary:{id:"suggestion-2-decision",scenario:"Camille a lu un rappel crédible trois matins sans écrire. Document et faits sont prêts. Le déjeuner permet régulièrement une phrase.",question:"Qu’est-ce qui convient à cet essai ?",options:[{id:"suggestion-2-count",text:"Garder le moment du matin et multiplier les répétitions avant de commencer le document.",feedback:"Davantage de répétitions teste la lecture, pas le départ manquant. Les notes interrogent le choix du moment. Le créneau du déjeuner permet une vraie phrase."},{id:"suggestion-2-cue",text:"Garder les mots crédibles, choisir le déjeuner et écrire une phrase.",feedback:"Cela change la condition qui bloquait l’action en gardant la tâche utile. Elle peut noter le signal et la phrase réellement produite. L’automaticité n’est pas nécessaire."},{id:"suggestion-2-prepare",text:"Utiliser la pause déjeuner pour peaufiner le rappel et préparer le matériel du lendemain.",feedback:"Préparer peut aider quand une ressource manque. Ici, matériel et consigne sont prêts. Une préparation supplémentaire laisserait encore la même phrase utile non écrite."}],bestOptionId:"suggestion-2-cue"}},carry:{takeaway:"Déclenche le geste utile, pas seulement les mots qui le précèdent.",followUp:{questionId:"suggestion-2-return",question:"Le signal choisi a-t-il mené au geste, à une demande ou seulement à lire le rappel ?",observationPrompt:"Que montrent tes notes sur les faits ?",adjustmentPrompt:"Que garderas-tu ou changeras-tu au prochain signal ?"}},goDeeper:{sections:[{heading:"Ce que le nombre de répétitions de Coué permet d’affirmer",paragraphs:["Le texte anglais de Coué de 1922 prescrit vingt répétitions à voix basse au réveil et au coucher, les yeux fermés, avec des nœuds pour compter. Il présente anecdotes, démonstrations et témoignages plutôt que des preuves d’interventions contrôlées. Vingt répétitions deux fois par jour décrit donc une pratique historique, pas des doses efficaces établies. Ces instructions ne permettent pas de savoir si les mots d’aujourd’hui servent ta tâche. (suggestion-S15)","Tu n’as pas besoin de recréer le rituel pour essayer une consigne crédible. Les anecdotes ne démontrent ni ses lois universelles opposant imagination et volonté, ni ses promesses de guérison. Garde les soins prescrits ; n’utilise pas une phrase rassurante pour expliquer de nouveaux symptômes physiques. La leçon demande si le signal choisi soutient un geste utile. Lire une fois est une préparation facultative ; l’action suivante fait avancer la tâche."]},{heading:"Un contexte récurrent ne crée pas une habitude instantanée",paragraphs:["Lally et ses collègues ont suivi quatre-vingt-seize volontaires ayant choisi un geste alimentaire, de boisson ou d’activité dans un contexte récurrent. Répétition et automaticité ont été suivies pendant quatre-vingt-quatre jours. Parmi quatre-vingt-deux participants avec assez de données, trente-neuf avaient des modèles satisfaisants ; leurs délais estimés vers l’automaticité presque maximale variaient beaucoup. Certaines estimations dépassaient la période observée. La médiane de soixante-six jours n’était pas une échéance pour chaque comportement. (suggestion-S09)","C’était une étude observationnelle des habitudes, pas un essai de la formule Coué, des répétitions au coucher ou d’une routine de candidature. Déjeuner et minimum court sont des choix ODA. Un essai peut montrer que le moment s’est présenté et que la tâche était possible. Il ne prouve ni que la phrase cause une réussite, ni une automaticité dès vendredi. Au bilan de demain, distingue préparation, arrivée du signal et production réelle."]}],sourceIds:["suggestion-S15","suggestion-S09"]}},{schemaVersion:2,revision:2,id:"suggestion-3",courseId:"suggestion",locale:"fr",title:"Tu évites les retours ? Fais parler tes valeurs",goal:"Si les retours bloquent, relie une valeur choisie à une correction.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Les commentaires te braquent ? Laisse une valeur guider une vraie correction.",reason:{id:"suggestion-3-reason",label:"Quel commentaire utile repousses-tu ? À quel prix ?",kind:"text",maxLength:160,optional:!0,suggestions:["Phrase vague ; la personne qui relit reste perdue","Date manquante ; candidature incomplète","Besoin d’une précision avant de modifier","Aucun retour utilisable pour le moment"]},why:{id:"suggestion-3-why",label:"Quelle place ce geste ferait-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Réfléchir aux valeurs n’est pas se complimenter. Avec des informations de santé, cette réflexion a montré de petits bénéfices moyens pour l’accueil des messages et le comportement ultérieur. Une note seule n’a pas d’effet démontré sur toute tâche ou sur l’humeur.","Essaie si tes notes montrent des retours évités. Garde la tâche. Si utile, une valeur comme apprendre peut guider une correction. Essaie « Vérifie ce fait », puis corrige-le ou demande une précision. Tes raisons peuvent être mêlées ; tes responsabilités familiales comptent aussi. Ni raison parfaite, ni accord avec chaque commentaire, ni confiance accrue ne sont requis."],example:{title:"Camille utilise un retour",text:"Après déjeuner, Camille voit un commentaire : sa phrase de candidature est vague. Apprendre compte pour elle, mais elle veut fermer le document. Elle utilise « Ajoute un exemple précis » et décrit une tâche accomplie. Le reste nécessite encore du travail. Elle note la correction sans prétendre que sa valeur lui a donné confiance."}},move:{invitation:"Garde ta tâche ; exemples : la correction de Camille.",instructions:["Garde geste et signal ; précise le commentaire et la correction correspondante.","Une valeur peut aider ; corriger ou demander une précision fournit le geste."],prompts:[],suggestions:{action:["Ajouter un exemple professionnel à la candidature","Demander quelle phrase nécessite des détails"],minimum:["Enregistrer la phrase avec un exemple","Envoyer la demande de précision sur la candidature"],cue:["À la fin du déjeuner","À l’arrivée du commentaire de relecture"],place:["À la table de ma cuisine","Dans le document de candidature"],minutes:[2,1,3],fallback:["Ajouter un fait professionnel connu sans me défendre","Demander quel détail nécessite une précision"],observation:["La phrase corrigée ou la question envoyée","Ai-je utilisé le retour pertinent ?"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Ajouter un exemple professionnel à la candidature",minimum:"Enregistrer la phrase avec un exemple",minutes:2,cueHint:"À la fin du déjeuner",placeHint:"À la table de ma cuisine",obstacleHint:"J’ai envie de défendre tout le document",fallbackHint:"Ajouter un fait professionnel connu sans me défendre",observationHint:"La phrase corrigée ou la question envoyée"},stopRule:"Garde tes limites face aux retours hostiles ou dangereux ; choisis protection ou soutien si nécessaire.",accessibleAlternative:"Choisis une valeur privée, une consigne neutre ou une aide ; écrire sur les valeurs reste facultatif."},result:{question:"As-tu fait la correction ou posé ta question ?",observationPrompt:"Qu’as-tu fait pendant cet essai ? Qu’est-ce qui t’a freiné ?"},judgment:{primary:{id:"suggestion-3-decision",scenario:"Une personne de confiance signale une phrase vague à Camille. Elle a un exemple concret et souhaite apprendre, mais se sent sur la défensive.",question:"Qu’est-ce qui convient à cet essai ?",options:[{id:"suggestion-3-strengths",text:"Lister d’abord ses forces, puis reprendre la phrase quand la critique sera plus facile à entendre.",feedback:"Réfléchir à ses forces peut lui plaire, mais l’exemple utile est disponible maintenant. Sa valeur peut guider une correction sans exiger qu’elle se sente à l’aise."},{id:"suggestion-3-correct",text:"Utiliser « Ajoute un exemple » et modifier la phrase avec le fait disponible.",feedback:"Apprendre devient un choix concret sur la même tâche. La correction fournit un fait observable, sans exiger une meilleure humeur ni l’accord avec chaque commentaire."},{id:"suggestion-3-reassure",text:"Demander confirmation de ses capacités générales avant de faire la correction précise.",feedback:"Être rassurée pourrait aider, mais ses capacités générales ne sont pas l’information manquante. Elle dispose d’un commentaire précis et d’un fait. Une clarification est utile seulement si les détails restent flous."}],bestOptionId:"suggestion-3-correct"}},carry:{takeaway:"Une valeur devient utile quand elle guide un choix concret aujourd’hui.",followUp:{questionId:"suggestion-3-return",question:"As-tu fait la correction ou demandé une précision ? Qu’est-ce qui reste flou ?",observationPrompt:"Que montrent tes notes sur les faits ?",adjustmentPrompt:"Que garderas-tu ou changeras-tu au prochain signal ?"}},goDeeper:{sections:[{heading:"Les preuves sur les valeurs dépendent du contexte",paragraphs:["Epton et ses collègues ont réuni des tests d’auto-affirmation associés à des informations de santé. Ils trouvaient de petits effets moyens sur l’accueil des messages, les intentions et le comportement. Les 144 tests couvrent différents résultats ; ce ne sont pas nécessairement 144 études distinctes. Leurs effectifs ne doivent pas être additionnés comme des personnes uniques. Réfléchir aux valeurs dans ce contexte diffère de répéter des compliments ou de se déclarer excellent avant d’examiner les retours. (suggestion-S02)","Une synthèse récente de Zhang et ses collègues rapportait de petits bénéfices pour le bien-être dans soixante-sept articles et 129 tests indépendants chez des populations non cliniques. Le résumé universitaire disponible donne une vue générale, sans les méthodes complètes nécessaires pour évaluer mesure précise de l’effet, effectif total, intervalles de confiance et durées de suivi. Cela élargit le contexte au-delà des messages de santé, mais ne prouve pas l’effet de l’exercice court d’aujourd’hui, valeur puis correction, ni d’une formule particulière d’affirmation."]},{heading:"Utilise une valeur sans promettre un effet universel",paragraphs:["Une grande réplication de Hanselman et ses collègues auprès de collégiens ne trouvait pas de bénéfice significatif de l’auto-affirmation sur les notes ciblées dans la nouvelle cohorte. La précision annoncée permettait d’écarter des bénéfices d’au moins 0,10 écart-type. Cela ne rend pas toute réflexion sur les valeurs inutile et ne réfute pas les travaux sur les messages de santé : contexte, population et résultat comptent. Un résultat scolaire ne promet ni confiance adulte ni performance généralement accrue. (suggestion-S12)","La question ODA est plus précise : penser à une valeur t’aide-t-il à utiliser un retour pertinent sur ta tâche en cours ? La note courte facultative et cette correction précise sont des adaptations. Apprendre, assumer tes responsabilités familiales ou trouver un emploi peut compter pour plusieurs raisons à la fois. Aucune pureté des motivations n’est exigée. Distingue les retours utiles des insultes ou demandes dangereuses. Note la correction ou la demande d’aide réelle, pas une description plus positive de toi."]}],sourceIds:["suggestion-S02","suggestion-S05","suggestion-S12"]}},{schemaVersion:2,revision:2,id:"suggestion-4",courseId:"suggestion",locale:"fr",title:"Le trac revient ? Donne-toi un conseil clair",goal:"Quand le trac te bloque, essaie ton prénom puis utilise ta phrase préparée.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Ton idée est prête, mais tu ressasses ton trac ? Parle-toi, puis utilise-la.",reason:{id:"suggestion-4-reason",label:"Qu’apporte cette analyse ? Quelle occasion risques-tu de manquer ?",kind:"text",maxLength:160,optional:!0,suggestions:["Mots peaufinés ; invitation à parler manquée","Réconfort bref ; question prête reportée","Question floue ; préparation nécessaire","Aucune occasion manquée jusque-là"]},why:{id:"suggestion-4-why",label:"Quelle place ce geste ferait-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Dans des expériences courtes de stress social, les participants réfléchissaient avec leur prénom ou « tu » plutôt que « je ». Une étude trouvait une meilleure performance selon les observateurs, sans baisse significative d’anxiété avant l’échange. Le recul n’impose pas de supprimer le trac.","Si surveiller ton trac a bloqué ta tâche, garde les mêmes faits : « Je suis préparée et nerveuse » devient « Camille est préparée et nerveuse ». Ajoute une consigne utile ; utilise ta phrase dans un échange sûr. Garde une ancienne consigne si elle aide. Cette réflexion est facultative ; participer constitue l’essai réel."],example:{title:"Camille pose sa question",text:"Camille a sa question de candidature, mais ses notes du déjeuner montrent qu’elle analysait l’impression qu’elle ferait. Avant un appel sans risque, elle dit : « Camille est préparée et nerveuse. Pose la question sur l’exemple. » Elle la pose. La personne qui relit doit réfléchir avant de répondre. Elle note sa participation et la réponse attendue, sans prétendre qu’un pronom a effacé l’anxiété."}},move:{invitation:"Garde ton geste ; exemples : question de relecture.",instructions:["Garde geste et signal ; la réflexion prépare seulement, si tu le souhaites.","Pour un premier échange, précise la question réelle et une occasion sûre.","Pose ta question ou partage ta phrase ; la première personne convient aussi."],prompts:[],suggestions:{action:["Demander quel exemple professionnel ajouter","Partager la phrase de candidature pour relecture"],minimum:["Demander quel exemple professionnel manque","Envoyer la phrase de candidature pour avis"],cue:["Quand la personne qui relit invite les questions","À la fin du déjeuner"],place:["Pendant l’appel de relecture prévu","Dans le fil de messages de relecture"],minutes:[2,1,3],fallback:["Demander maintenant « Quel exemple manque ? »","Envoyer la question sur l’exemple professionnel"],observation:["Ai-je posé la question sur l’exemple professionnel ?","La réponse, ou son attente"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Demander quel exemple professionnel ajouter",minimum:"Demander quel exemple professionnel manque",minutes:2,cueHint:"Quand la personne qui relit invite les questions",placeHint:"Pendant l’appel de relecture prévu",obstacleHint:"J’analyse encore au lieu de poser la question prête",fallbackHint:"Demander maintenant « Quel exemple manque ? »",observationHint:"Ai-je posé la question sur l’exemple professionnel ?"},stopRule:"Suspends les échanges dangereux. Cherche un soutien qualifié face à une détresse persistante ou à des difficultés importantes au quotidien.",accessibleAlternative:"Utilise un message sûr, la langue des signes ou une aide ; ton prénom reste facultatif."},result:{question:"As-tu utilisé ta phrase préparée pendant l’échange réel ?",observationPrompt:"Qu’as-tu fait pendant cet essai ? Qu’est-ce qui t’a freiné ?"},judgment:{primary:{id:"suggestion-4-decision",scenario:"La question de Camille est claire. La personne qui relit l’invite à la poser avant la fin de l’appel prévu. Camille a le trac et a déjà réfléchi brièvement.",question:"Qu’est-ce qui convient à cet essai ?",options:[{id:"suggestion-4-name",text:"Répéter encore en privé pour peaufiner les mots, puis attendre une prochaine invitation à parler.",feedback:"Répéter peut améliorer les mots. La question est déjà claire et l’appel se termine. Cette occasion sûre peut être saisie ; le prénom est facultatif, une consigne factuelle à la première personne convient aussi."},{id:"suggestion-4-analyze",text:"Détailler davantage sa nervosité en privé avant de décider si elle participe.",feedback:"Une réflexion détaillée pourrait éclairer autre chose, mais prolonge ici la préparation. Ce qui bloque maintenant, c’est utiliser une phrase prête pendant l’occasion sûre disponible."},{id:"suggestion-4-use",text:"Dire « Camille est préparée et nerveuse », puis poser sa vraie question.",feedback:"Les faits restent les mêmes et la préparation débouche sur une participation. Les expériences ne promettent pas moins d’anxiété avant l’échange. Elle peut noter la phrase réelle et la réponse."}],bestOptionId:"suggestion-4-use"}},carry:{takeaway:"Le recul doit mener à un conseil et un geste, pas à t’analyser encore.",followUp:{questionId:"suggestion-4-return",question:"Le recul a-t-il mené à ta vraie phrase ou à plus de préparation ?",observationPrompt:"Que montrent tes notes sur les faits ?",adjustmentPrompt:"Que garderas-tu ou changeras-tu au prochain signal ?"}},goDeeper:{sections:[{heading:"Change de point de vue en gardant les faits",paragraphs:["Kross et ses collègues ont mené sept expériences avec 585 personnes, surtout dans des contextes étudiants et d’évaluation sociale. Dans l’étude 2, les participants réfléchissaient seuls trois minutes avant de rencontrer une personne inconnue. Les consignes utilisaient leur prénom et des pronoms autres que la première personne ; le groupe de comparaison utilisait « je » et « moi ». La performance d’interaction évaluée par des observateurs était meilleure avec le prénom. L’anxiété avant l’échange ne diminuait pas significativement ; le rétablissement après était plus net. (suggestion-S03)","Une illustration honnête garde le même contenu. Compare « Je suis préparée et nerveuse ; commence par un fait concret » et « Camille est préparée et nerveuse ; commence par un fait concret ». Comparer une critique dure avec « je » à un conseil bienveillant avec le prénom changerait aussi la bienveillance, sans isoler le point de vue. La version courte d’ODA, conseil puis phrase, est une adaptation, pas le protocole de trois minutes ni un traitement de l’anxiété sociale."]},{heading:"Un conseil clair a encore besoin d’une occasion",paragraphs:["Ces expériences courtes ne démontrent ni bénéfice durable, ni pronom obligatoire, ni avantage universel. Penser avec « je » n’est pas nocif en soi. Tu peux préférer « Je peux poser la question », des consignes neutres ou aucune réflexion. Le cours continue d’examiner ta tâche utile, pas une forme grammaticale précise pour te parler. (suggestion-S03)","Note l’échange réel comme action s’il constitue la prochaine étape de ta tâche. Si tu prépares seulement la phrase, note une préparation sans inventer de participation. Sans créneau, tu peux signaler l’absence d’occasion. Détresse persistante, difficultés majeures au quotidien ou pensées de te faire du mal nécessitent une aide qualifiée ; réfléchir avec ton prénom ne la remplace pas. Protège-toi dans les situations dangereuses et utilise un soutien local adapté. Changer de pronom ne rend pas la maltraitance sûre et ne supprime pas les besoins de soins. (suggestion-S20)"]}],sourceIds:["suggestion-S03","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-5",courseId:"suggestion",locale:"fr",title:"Une erreur ? Précise le prochain geste",goal:"Une erreur revient ? Teste une consigne sur un élément réel de ta tâche.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Encore une erreur, encore un jugement ? Donne une consigne précise au prochain essai.",reason:{id:"suggestion-5-reason",label:"Quel jugement a retardé ta dernière correction ?",kind:"text",maxLength:160,optional:!0,suggestions:["« Je suis négligent » ; date inchangée","« Ce document est fichu » ; vérification abandonnée","Aucun jugement n’a retardé ma correction","Pas encore d’erreur ; je risque de me juger"],help:"Pas encore d’erreur ? Quel jugement pourrait retarder la prochaine correction ?"},why:{id:"suggestion-5-why",label:"Quelle place ce geste ferait-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Les études sportives sur le discours intérieur trouvaient un bénéfice moyen de performance avec des tâches et entraînements variés. Les consignes convenaient parfois mieux aux gestes précis. Ces comparaisons ne prouvent ni supériorité universelle sur l’encouragement, ni même effet au bureau.","Relis tes notes. Pour un détail récurrent, précise la consigne : « Vérifie la date. » Si nécessaire, essaie un exemple facile, puis un élément réel. Note-les séparément. Sans savoir corriger l’erreur, demande une explication. Plus de motivation ne fournit ni connaissance manquante ni correction terminée."],example:{title:"Camille vérifie la date",text:"La candidature de Camille contient deux dates incohérentes. À la fin du déjeuner, elle dit « Vérifie la date ». Elle s’entraîne sur un exemple copié, puis vérifie et corrige une vraie date du document. Une autre incohérence reste. Elle note la correction et demande comment vérifier l’entrée peu claire, sans prétendre que la consigne a résolu tout le document."}},move:{invitation:"Garde ton élément et ton signal ; exemples : correction d’une date.",instructions:["Garde l’élément et le créneau ; précise la vraie consigne de vérification.","Dans l’exemple, utilise « Vérifie la date » et corrige une entrée.","Sans connaître la méthode, choisis « Adapter ce geste » pour demander une explication précise."],prompts:[],suggestions:{action:["Dire « Vérifie la date » ; corriger une entrée","Comparer une date de candidature au document original"],minimum:["Enregistrer une date corrigée dans la candidature","Noter si la date de candidature correspond"],cue:["À la fin du déjeuner","En arrivant à la rubrique des dates"],place:["À la table de ma cuisine","Dans le document de candidature"],minutes:[3,2,1],fallback:["Demander comment vérifier la date","Consulter le document professionnel original daté"],observation:["La correction réelle ou la demande d’explication","Exercice d’essai distinct du travail réel"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Dire « Vérifie la date » ; corriger une entrée",minimum:"Enregistrer une date corrigée dans la candidature",minutes:3,cueHint:"À la fin du déjeuner",placeHint:"À la table de ma cuisine",obstacleHint:"Je ne sais pas vérifier la bonne date",fallbackHint:"Demander comment vérifier la date",observationHint:"La correction réelle ou la demande d’explication"},stopRule:"Besoin d’une explication ? Choisis « Adapter ce geste », puis « Soutien ». Pour une tâche lourde de conséquences, demande un avis professionnel adapté.",accessibleAlternative:"Utilise une consigne écrite, un exemple accessible, la dictée ou une aide."},result:{question:"As-tu corrigé un élément réel ou demandé une explication ?",observationPrompt:"Qu’as-tu fait pendant cet essai ? Qu’est-ce qui t’a freiné ?"},judgment:{primary:{id:"suggestion-5-decision",scenario:"Camille sait vérifier une date, mais saute régulièrement cette étape. Une vraie entrée de sa candidature nécessite une correction.",question:"Qu’est-ce qui convient à cet essai ?",options:[{id:"suggestion-5-drive",text:"Utiliser « Continue » en traitant les entrées restantes pour garder son élan.",feedback:"L’élan compte, mais les notes montrent une vérification sautée. Préciser ce détail et le tester sur une vraie entrée évite de propager l’erreur au reste."},{id:"suggestion-5-detail",text:"Utiliser « Vérifie la date » sur une vraie entrée, puis la corriger.",feedback:"La consigne correspond au blocage observé et produit une correction réelle. Cet essai personnel renseigne sur son adéquation, sans prouver son effet causal."},{id:"suggestion-5-all",text:"Écrire une petite liste de vérification des dates, intitulés et mise en forme avant de reprendre l’entrée de candidature.",feedback:"Une liste courte peut éviter plusieurs oublis. Ici, les notes désignent une date non vérifiée et Camille connaît la méthode. Elle peut corriger cette entrée d’abord, puis ajouter d’autres vérifications selon les besoins observés."}],bestOptionId:"suggestion-5-detail"}},carry:{takeaway:"Corrige le prochain détail possible ; demande une explication si la compétence manque.",followUp:{questionId:"suggestion-5-return",question:"Que s’est-il passé avec la correction ou la demande d’explication ? Quel détail reste à vérifier ?",observationPrompt:"Que montrent tes notes sur les faits ?",adjustmentPrompt:"Que garderas-tu ou changeras-tu au prochain signal ?"}},goDeeper:{sections:[{heading:"Une moyenne sportive ne promet rien au bureau",paragraphs:["La méta-analyse d’Hatzigeorgiadis et ses collègues réunissait trente-deux études et soixante-deux effets. Le tableau original rapportait 2 741 participants. La différence standardisée corrigée globale de performance était 0,48, avec un intervalle de confiance de 0,38 à 0,58. Les travaux portaient sur des tâches sportives et motrices chez des étudiants et sportifs ; certains n’avaient pas de comparaison contrôlée. Ce résultat regroupé ne prédit pas l’effet sur ta candidature et ne choisit pas ta règle de vérification. (suggestion-S04)","Les estimations variaient selon motricité fine ou globale, consignes ou encouragements, et entraînement préalable. Ce ne sont ni des comparaisons randomisées de doses, ni un classement universel des techniques. Elles ne prédisent pas un bénéfice de 0,48 pour un tableur, une candidature ou une conversation. Le test d’aujourd’hui, une consigne sur un élément réel, est un essai de transfert ODA. Un résultat favorable montre ce qui s’est passé pour cet élément, pas pourquoi ni ce qui arrivera à chaque essai suivant."]},{heading:"La consigne doit préciser un détail utilisable",paragraphs:["La consigne doit répondre au problème réellement noté. « Vérifie la date » décrit une étape ; « sois excellent » n’explique aucune correction. Un exemple facile peut préparer la consigne, sans terminer l’élément réel. Si la méthode t’est inconnue, demander une explication précise est un geste utile en soi. La synthèse sportive ne valide ni le modèle complet de Gallwey, ni deux entités cérébrales littérales, ni un scénario historique non vérifié. (suggestion-S04)","Tu peux changer la consigne après un décalage observé, la garder après un essai réalisable ou arrêter ce discours intérieur s’il met la pression. N’ajoute pas plusieurs consignes pour rendre le plan plus impressionnant. Les notes ODA servent à repérer le blocage, pas à juger ton caractère. Une détresse persistante ou importante appelle un soutien qualifié, pas des répétitions renforcées. (suggestion-S20)"]}],sourceIds:["suggestion-S04","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-6",courseId:"suggestion",locale:"fr",title:"Au coucher, laisse la place au sommeil",goal:"Obstacle de demain flou ? Planifie en journée ; note l’essai réel séparément.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Ton discours motivant te tient éveillé ? Prépare demain pendant la journée.",reason:{id:"suggestion-6-reason",label:"Que faut-il prévoir ? Quand faut-il te reposer ?",kind:"text",maxLength:160,optional:!0,suggestions:["Déjeuner chargé ; choisir un autre moment en journée","Plan prêt ; arrêter les vérifications au coucher","Aucun problème de planification observé jusque-là"]},why:{id:"suggestion-6-why",label:"Quelle place ce geste ferait-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Le sommeil traite les souvenirs, sans fenêtre démontrée pour commander le subconscient. Prévoir résultat, obstacle et réponse est étayé pour divers objectifs. Les recherches ne valident pas une rêverie au coucher suivie d’un plan le lendemain matin.","Prépare ta réponse à l’obstacle non résolu en journée. Précise ensemble résultat souhaité, obstacle et réponse possible. Garde la même partie utile de ta tâche. Planifier prépare ; note l’essai ultérieur séparément. Arrête de réfléchir au coucher si cela te tient plus éveillé. Ni scène, ni gratitude ressentie, ni répétition ne sont nécessaires pour valider le plan."],example:{title:"Camille prépare avant le dîner",text:"À 18 h 30, Camille veut écrire demain sa phrase de candidature, mais prévoit un petit-déjeuner chargé. Elle choisit la fin du déjeuner : si la table est occupée, elle dictera une phrase. C’est une préparation. Le lendemain, la table est prise ; elle dicte une phrase utilisable et note la production réelle. Au coucher, elle ne planifie plus."}},move:{invitation:"Garde ta tâche ; exemples : rédaction en journée par Camille.",instructions:["Garde geste, minimum et signal, sauf obstacle nécessitant un changement.","Prévois ensemble résultat, obstacle et réponse en journée ; note le geste ultérieur séparément."],prompts:[],suggestions:{action:["Après déjeuner, écrire une phrase sur mon expérience","Après déjeuner, dicter une phrase sur mon expérience"],minimum:["Enregistrer une phrase factuelle de candidature","Enregistrer une phrase dictée sur mon expérience"],cue:["À la fin du déjeuner","Après ma boisson du matin"],place:["À la table de ma cuisine","Dans le document de candidature"],minutes:[2,1,3],fallback:["Dicter la phrase de candidature au déjeuner","Après dîner, écrire une phrase sur mon expérience"],observation:["Table disponible ? Solution de repli utilisée ?","La phrase réelle après la préparation"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Après déjeuner, écrire une phrase sur mon expérience",minimum:"Enregistrer une phrase factuelle de candidature",minutes:2,cueHint:"À la fin du déjeuner",placeHint:"À la table de ma cuisine",obstacleHint:"La table de ma cuisine est occupée",fallbackHint:"Dicter la phrase de candidature au déjeuner",observationHint:"Table disponible ? Solution de repli utilisée ?"},stopRule:"Arrête de planifier au coucher si cela te tient plus éveillé. Préserve ton repos et cherche une aide adaptée si les difficultés persistent.",accessibleAlternative:"Planifie en journée par écrit, oralement ou avec une aide ; les images sont facultatives."},result:{question:"As-tu fait la partie réelle au moment du signal ?",observationPrompt:"Qu’as-tu fait pendant cet essai ? Qu’est-ce qui t’a freiné ?"},judgment:{primary:{id:"suggestion-6-decision",scenario:"Camille a un plan écrit pour le déjeuner. Au lit, imaginer demain devient une vérification anxieuse répétée et elle se sent plus éveillée.",question:"Qu’est-ce qui convient à cet essai ?",options:[{id:"suggestion-6-finish",text:"Terminer l’analyse des obstacles au lit pour se sentir pleinement rassurée sur le plan de demain.",feedback:"Tout régler est tentant, mais un plan réalisable est déjà écrit et cette vérification entretient l’éveil. Elle peut arrêter maintenant et revoir les détails plus tôt en journée si nécessaire."},{id:"suggestion-6-stop",text:"Arrêter la scène, garder le signal écrit et revenir au repos.",feedback:"Cela protège le repos sans abandonner le geste possible de demain. Les travaux sur mémoire et sommeil n’établissent aucun rituel obligatoire au coucher. L’essai ultérieur aura ses propres notes."},{id:"suggestion-6-replace",text:"Remplacer la scène par une phrase positive répétée jusqu’à ce que les vérifications se calment.",feedback:"Un autre rituel peut prolonger le même effort éveillé. Aucune répétition n’est nécessaire pour valider le plan. Elle peut garder le signal et cesser de planifier maintenant."}],bestOptionId:"suggestion-6-stop"}},carry:{takeaway:"Prépare le plan en journée. Distingue repos et geste ultérieur dans tes notes.",followUp:{questionId:"suggestion-6-return",question:"La réponse à l’obstacle a-t-elle aidé ton geste sans prolonger l’effort au coucher ?",observationPrompt:"Que montrent tes notes sur les faits ?",adjustmentPrompt:"Que garderas-tu ou changeras-tu au prochain signal ?"}},goDeeper:{sections:[{heading:"La science du sommeil ne valide pas un rituel",paragraphs:["La synthèse de Paller, Creery et Schechtman aborde la réactivation de connaissances pendant le sommeil et les possibilités limitées d’apprentissage d’associations simples. C’est une synthèse narrative sans effet regroupé pour l’autosuggestion. Traiter les souvenirs ne prouve ni un subconscient réceptif sans esprit critique avant le sommeil, ni un avantage des affirmations en somnolant, ni des compétences complexes installées par une phrase. Ce sont des affirmations différentes. (suggestion-S10)","La présentation éditoriale de Murphy situe son livre et valorise croyance et imagination. Elle ne démontre pas l’efficacité de son rituel du coucher. Elle ne fournit aucune preuve contrôlée pour cet ensemble et ne valide pas un scénario précis de répétition. Si planifier te tient éveillé, déplace la préparation nécessaire plus tôt dans la journée et réserve le coucher au repos. Une image volontaire en journée reste un choix ODA, pas une preuve d’attraction, de guérison ou de mécanisme spécial au coucher. (suggestion-S16)"]},{heading:"Garde ensemble résultat souhaité, obstacle et réponse",paragraphs:["La méta-analyse de Wang et ses collègues sur le contraste mental avec plans « si… alors… » réunissait vingt et un articles, vingt-quatre effets indépendants et 15 907 participants. Elle trouvait un bénéfice moyen pour atteindre les objectifs ; la correction du biais de publication réduisait l’estimation. Objectifs, méthodes et comparaisons variaient. Le résultat n’isole pas une phrase positive comme ingrédient actif et ne valide pas la fiche d’autosuggestion ODA complète. (suggestion-S06)","Utilise ce contraste pour répondre à un problème concret : quel résultat compte, quel obstacle est probable et quelle réponse est possible ? Travaille ces éléments ensemble, puis enregistre la partie réelle de la tâche avec son signal. Une note sur demain prépare aujourd’hui ; elle n’accomplit pas le travail de demain. Si l’obstacle demande des moyens, une protection ou une aide, choisis cette réponse pratique sans accuser tes croyances. Planifier plus tôt protège le temps de repos. Les recherches n’ont pas testé la séparation entre rêverie au coucher et plan le lendemain matin."]}],sourceIds:["suggestion-S10","suggestion-S16","suggestion-S06"]}},{schemaVersion:2,revision:2,id:"suggestion-7",courseId:"suggestion",locale:"fr",title:"Compte les gestes, pas les lectures de la fiche",goal:"Rassemble les notes de ta tâche et choisis ton prochain essai, consigne puis action.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Rappel lu, tâche intacte ? Fais le bilan ou prévois un premier essai.",reason:{id:"suggestion-7-reason",label:"D’après tes notes, que garder, changer ou arrêter ?",kind:"text",maxLength:160,optional:!0,suggestions:["Déjeuner utile ; garder ce moment","Matin chargé ; changer le signal","Répétitions pesantes ; arrêter de répéter","Aucun essai noté ; choisir un premier geste"]},why:{id:"suggestion-7-why",label:"Quelle place ce geste ferait-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["La fiche réunit phrase crédible, signal et réponse à l’obstacle. Cet ensemble n’est pas validé. Les recherches sur les plans ne prouvent pas que lire la fiche cause l’action.","Fais le point ou choisis un premier essai. Distingue lecture, préparation, gestes réels et bilans. Garde les mots acceptables et un moment adapté ; change un blocage observé. Enregistre le geste et son minimum pour la prochaine occasion. Les essais futurs restent prévus jusqu’à ton compte rendu. Si les mots pèsent, simplifie-les ou arrête. Ni miroir, ni rituel, ni croyance renforcée nécessaires."],example:{title:"La prochaine semaine de Camille",text:"Dimanche, Camille relève cinq lectures et trois productions utiles de candidature. Deux départs manqués venaient de matins chargés ; le déjeuner a fonctionné deux fois. Elle garde « Note un fait concret », abandonne les images et prévoit un essai lundi après déjeuner. Lundi, elle écrit une phrase à retravailler. Elle la note ; les autres dates restent prévues."}},move:{invitation:"Garde ton geste et minimum ; exemples de candidature.",instructions:["Garde geste, minimum, signal et lieu ; change seulement le blocage observé.","Sans notes, précise un premier geste et son minimum avant d’enregistrer.","Utilise « Adapter ce geste » pour demander de l’aide ; les dates futures restent des plans."],prompts:[],suggestions:{action:["Dire « Vérifie la date » ; corriger une entrée","Comparer une date de candidature au document original"],minimum:["Enregistrer une date corrigée dans la candidature","Noter si la date de candidature correspond"],cue:["À la fin du déjeuner","En arrivant à la rubrique des dates"],place:["À la table de ma cuisine","Dans le fil de messages de relecture"],minutes:[2,1,3],fallback:["Arrêter de lire ; vérifier une date de candidature","Demander quelle source utiliser pour la date"],observation:["Corrections réelles distinctes des lectures de fiche","Créneau du déjeuner et consigne adaptés ?"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Dire « Vérifie la date » ; corriger une entrée",minimum:"Enregistrer une date corrigée dans la candidature",minutes:2,cueHint:"À la fin du déjeuner",placeHint:"À la table de ma cuisine",obstacleHint:"Je relis au lieu de vérifier la date de candidature",fallbackHint:"Arrêter de lire ; vérifier une date de candidature",observationHint:"Corrections réelles distinctes des lectures de fiche"},stopRule:"Pour la tâche, choisis « Adapter ce geste », puis « Soutien ». Arrête les mots qui aggravent la détresse ; consulte si la détresse persiste ou gêne ton quotidien. Garde les soins prescrits.",accessibleAlternative:"Utilise une note privée accessible, des mots neutres ou une aide ; aucun miroir nécessaire."},result:{question:"As-tu fait la prochaine partie ou le geste de soutien choisi ?",observationPrompt:"Qu’as-tu fait pendant cet essai ? Qu’est-ce qui t’a freiné ?"},judgment:{primary:{id:"suggestion-7-decision",scenario:"Camille lisait sa fiche chaque jour, mais n’a écrit qu’une fois au déjeuner. Les matins étaient chargés ; la consigne restait crédible.",question:"Qu’est-ce qui convient à cet essai ?",options:[{id:"suggestion-7-repeat",text:"Garder le plan du matin puisque lire la fiche chaque jour montre que la routine s’installe.",feedback:"La lecture quotidienne est un fait réel, mais pas le résultat d’écriture choisi. Le signal menait rarement au travail. Elle peut tester le créneau du déjeuner."},{id:"suggestion-7-increase",text:"Ajouter une lecture le soir pour mieux se souvenir de la phrase crédible.",feedback:"La mémoire peut compter, mais les faits disponibles pointent les matins chargés. Lire davantage change la répétition sans changer le signal de la tâche. Elle peut tester d’abord le blocage observé."},{id:"suggestion-7-revise",text:"Garder la phrase crédible, choisir le déjeuner et prévoir une vraie partie à écrire.",feedback:"Cela garde ce qui convenait et change le moment lié aux départs manqués. La prochaine partie reste prévue jusqu’au récit des faits. Le retour du lendemain permettra d’évaluer ce nouvel essai."}],bestOptionId:"suggestion-7-revise"}},carry:{takeaway:"Garde les mots utiles avec un geste possible, des notes fidèles et un prochain choix.",followUp:{questionId:"suggestion-7-return",question:"Que s’est-il passé avec ton geste ou ta demande d’aide ? Que faut-il changer ?",observationPrompt:"Que montrent tes notes sur les faits ?",adjustmentPrompt:"Que garderas-tu ou changeras-tu au prochain signal ?"}},goDeeper:{sections:[{heading:"La fiche complète est un choix de conception",paragraphs:["Le cours associe des mots crédibles, un signal, une partie réelle de tâche, une réponse à l’obstacle et un bilan. Cet ensemble est une conception ODA, pas une intervention contrôlée. La synthèse de Wang et ses collègues soutient le contraste mental avec plans « si… alors… » pour divers objectifs. Elle ne montre pas que chaque élément de fiche aide ou que la lire cause une tâche accomplie. (suggestion-S06)","Utilise la fiche comme rappel bref du plan enregistré, sans nouvelle obligation. Examine la préparation séparément de la production utile. Lire une fiche peut être noté honnêtement sans compter comme écrire, demander ou corriger. Garde un blocage observé en vue pour que le prochain essai réponde à une question précise. Des notes personnelles favorables renseignent sur l’adéquation du plan ; elles ne prouvent pas la cause et ne garantissent pas la même réussite chaque semaine."]},{heading:"Aucun nouveau rituel nécessaire pour finir",paragraphs:["L’étude observationnelle de Lally portait sur alimentation, boisson et activité répétées à des moments récurrents. Elle ne testait pas les phrases positives et ne garantissait aucun délai d’automaticité. Les occasions de la semaine suivante et le rythme de bilan ODA organisent ton essai ; ce ne sont ni une dose testée ni une obligation de série sans interruption. Les essais réels sur la tâche restent distincts de la fin de l’apprentissage. (suggestion-S09)","Le site de Hay décrit des affirmations au miroir et un programme de vingt et un jours. Aucun essai contrôlé de cet ensemble n’a été trouvé dans la revue des preuves ; cela ne prouve pas qu’il n’a jamais été étudié. Ici, le miroir n’a aucune supériorité établie et vingt et un jours n’est pas un délai d’habitude. Note privée, rappel accessible ou absence de fiche peuvent convenir. Termine en poursuivant la même tâche utile, en ajustant à partir des faits et en préservant sécurité, repos et soins prescrits. (suggestion-S18)"]}],sourceIds:["suggestion-S06","suggestion-S09","suggestion-S18"]}}],n=[{id:"suggestion-1",practice:["Précise une situation ordinaire que tu voudrais aborder autrement cette semaine.","Compare la critique familière à une consigne neutre crédible ; images et encouragements restent facultatifs.","Essaie la consigne sur une partie utile de la tâche ; note séparément action réelle et pression éventuelle."],reflection:"Quelle phrase te dis-tu le plus souvent ? Quel effet a-t-elle sur toi ?",question:"Que signifie l’autosuggestion dans ce cours ?",options:["Envoyer un ordre secret au subconscient qui change tout seul.","Répéter ensemble une phrase choisie, une image et une petite action.","Utiliser une technique de pensée qui remplace médicaments ou traitement."],correct:1,feedback:"Le cours propose un essai non testé, consigne puis action ; les images sont facultatives. Les études cliniques sur les attentes ne valident pas cette routine complète. L’autosuggestion ne remplace pas les traitements et ne garantit pas les résultats extérieurs.",photo:{id:"1461468611824-46457c0e11fd",alt:"Femme assise regardant la mer"}},{id:"suggestion-2",practice:["Si tu souhaites explorer le rituel historique de Coué, vérifie que les mots te conviennent ; le matériel de comptage reste facultatif.","Son texte anglais de 1922 décrivait vingt répétitions à voix basse : de l’histoire, pas une dose démontrée ni une pratique obligatoire au coucher.","Si tu essaies des mots volontairement, arrête en cas de détresse ou d’éveil accru. Distingue leur lecture de l’action réelle sur la tâche."],reflection:"Sans forcer, comment as-tu vécu la formule : apaisante, étrange, ennuyeuse ?",question:"Quelle attitude Coué recommandait-il pour sa formule ?",options:["Dire la phrase avec force, les dents serrées.","Dire la phrase doucement, à voix basse, et compter avec le cordon ou les perles.","Vérifier après chaque répétition si quelque chose a changé."],correct:1,feedback:"Coué recommandait une répétition détendue dans son récit historique. Les anecdotes ne prouvent ni loi universelle de l’imagination, ni dose efficace de vingt répétitions, ni guérison. L’édition anglaise consultée date de 1922.",photo:{id:"1762328490563-9b9c300fba3e",alt:"Personne tenant un cordon de perles"}},{id:"suggestion-3",practice:["Choisis une phrase positive ou une consigne neutre acceptable pour toi.","Tu peux noter sa crédibilité pour choisir les mots, sans seuil clinique ; modifie ou arrête si cela accentue la détresse.","Tu peux réfléchir à une valeur importante, puis choisir une action concrète qui la sert."],reflection:"Quelle phrase te fait penser « oui, ça pourrait être vrai » ?",question:"Avec des résultats mitigés sur les affirmations positives, quels mots peux-tu tester ?",options:["Répéter plus souvent la phrase la plus audacieuse, même sans y croire.","Choisir une phrase crédible qui décrit ce que tu vas faire.","Ne jamais te dire aucune phrase positive."],correct:1,feedback:"Le premier résultat défavorable n’a pas été reproduit dans deux études suivantes. Des mots neutres ou centrés sur l’action sont un choix volontaire, pas un traitement démontré plus sûr. Les scores de crédibilité ne diagnostiquent pas l’estime de soi.",photo:{id:"1616628188467-8fb29f49bbe8",alt:"Main écrivant une note sur du papier blanc"}},{id:"suggestion-4",practice:["Choisis un moment difficile cette semaine et note quand il aura lieu.","Avant ce moment, prends deux minutes pour décrire la situation en te parlant avec ton prénom.","Dis-toi ensuite la phrase de soutien que tu donnerais à un ami dans cette situation."],reflection:"Comment ton ton a-t-il changé avec ton prénom ?",question:"Dans les expériences de Kross de 2014, quel discours intérieur aidait davantage face au stress social ?",options:["Te parler avec ton prénom ou « tu ».","Réfléchir longuement à la situation en utilisant seulement « je ».","Te motiver par des critiques dures."],correct:0,feedback:"De courtes expériences de stress social trouvaient une meilleure performance évaluée par des observateurs avec le prénom ou sans la première personne. L’étude 2 ne réduisait pas significativement l’anxiété avant l’échange ; le rétablissement après était plus net. Ce n’est pas un traitement.",photo:{id:"1641907173006-6b8930ae1191",alt:"Femme pensive regardant le ciel"}},{id:"suggestion-5",practice:["Choisis une tâche de la semaine difficile à apprendre ou à bien faire.","Écris un mot de consigne et un mot d’encouragement pour cette tâche.","Pendant la tâche, répète brièvement la consigne d’une voix calme et note le résultat sans le juger."],reflection:"Quelle consigne a réellement ramené ton attention sur la tâche ?",question:"Selon la méta-analyse, quand les consignes intérieures fonctionnaient-elles particulièrement bien ?",options:["Pour des tâches demandant précision et attention.","Seulement pour des tâches très apprises et automatiques.","Seulement au premier essai, sans aucune pratique."],correct:0,feedback:"Dans les études sportives, les consignes convenaient souvent aux gestes fins ou nouveaux ; certaines études n’avaient pas de groupe témoin. Comparer tâches et entraînements entre sous-groupes ne prouve ni classement universel, ni dose optimale, ni bénéfice équivalent au bureau.",photo:{id:"1523497804259-88c4c134ca90",alt:"Athlète se préparant à courir sur une piste"}},{id:"suggestion-6",practice:["Plus tôt en journée, en étant éveillé, précise ensemble résultat souhaité et obstacle réel.","Choisis une réponse possible et une partie utile réelle de la tâche ; les images facultatives restent une préparation.","Enregistre le signal de la tâche et note l’essai ultérieur séparément. Arrête de planifier au coucher si cela entretient l’éveil."],reflection:"Au réveil, que t’a rappelé la scène imaginée avant de dormir ?",question:"Quelle préparation respecte les limites des recherches sur l’autosuggestion ?",options:["Imaginer le résultat avec l’obstacle réel et un plan « si… alors… ».","Attendre que le subconscient attire seul argent et santé pendant le sommeil.","Imaginer uniquement le bon résultat sans aucun plan."],correct:0,feedback:"Prévoir résultat, obstacle et réponse est étayé pour divers objectifs. Cela ne valide ni rituel spécial en somnolant, ni séparation entre rêverie au coucher et plan le lendemain matin. Préserve le sommeil ; l’action ultérieure reste distincte.",photo:{id:"1757796859729-270d1e3ad4d5",alt:"Livre ouvert sur une table de nuit sous une lampe allumée"}},{id:"suggestion-7",practice:["Si une fiche t’aide, écris ta consigne crédible et, si souhaité, une image du premier geste ; choisis un format privé accessible.","Ajoute le signal réel et une réponse possible à l’obstacle ; lire la fiche ne réalise pas la tâche.","Choisis une date de bilan, puis compare essais et préparation après les faits ; une semaine n’est pas une dose validée."],reflection:"Après sept jours, que garderais-tu tel quel sur ta fiche ? Que changerais-tu ?",question:"Après sept jours, quelle façon d’examiner ta fiche d’autosuggestion serait la plus utile ?",options:["Te reprocher l’absence de changement.","Regarder ce qui a fonctionné et adapter phrase, image ou plan.","Commencer à dire une phrase plus audacieuse plus fort."],correct:1,feedback:"Examine les essais réels séparément des lectures de fiche. L’ensemble n’a pas été testé. Garde les mots utiles et modifie un blocage observé sans exiger miroir, croyance renforcée ou nouveau rituel.",photo:{id:"1484480974693-6ca0a78fb36b",alt:"Main écrivant une liste de vérification dans un carnet"}}],a={id:"suggestion",lang:"fr",title:"Ta petite voix te bloque ? Donne-toi une consigne",subtitle:"Sept leçons courtes. Des mots crédibles pour un geste utile, puis des ajustements à partir des faits.",description:"Choisis une tâche qui compte et teste une consigne crédible avec une action réelle. Améliore le signal, utilise les retours, réponds à un obstacle observé et poursuis le même essai la semaine suivante.",scope:"Un cours d’autosuggestion et de discours intérieur pour adultes. Ce n’est ni de l’hypnothérapie, ni un diagnostic, ni un traitement. L’autosuggestion ne remplace aucun médicament ni traitement en cours ; n’en arrête aucun sans en parler à ton médecin. Les livres affirmant qu’elle guérit les maladies ou attire l’argent ne sont pas soutenus par les recherches. Si tes pensées négatives sont très intenses ou que ton moral est bas depuis longtemps, contacte un professionnel de santé mentale. Si tu penses à te faire du mal ou te trouves en danger immédiat, appelle le numéro d’urgence local.",outcome:"Une consigne crédible liée à une tâche utile, des notes fidèles aux actions et un prochain essai guidé par les faits du quotidien.",photo:{id:"1779922811108-245a9403ef44",alt:"Silhouette d’une personne au sommet d’une colline à l’aube"},lessons:t.map((e,s)=>({...n[s],schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:e.idea.paragraphs,example:e.idea.example,deeper:e.goDeeper.sections,sources:[...new Set([...e.goDeeper.sourceIds,"suggestion-S20",...e.id==="suggestion-3"?["suggestion-S07","suggestion-S08"]:[]])],takeaway:e.carry.takeaway,visual:{kind:"steps",title:"Un même essai qui se poursuit",steps:[{label:"Déclencheur",text:"Choisis un créneau possible."},{label:"Agir",text:"Essaie le minimum utile."},{label:"Revenir",text:"Note les faits et choisis le prochain essai."}]}}))},r=Object.freeze(Object.defineProperty({__proto__:null,COURSE:a,SOURCES:i,SUGGESTION_LESSONS_V2:t},Symbol.toStringTag,{value:"Module"}));export{r as s};
